<?php

namespace Modules\LMS\Database\Seeders;

use Illuminate\Database\Seeder;
use Modules\LMS\Models\Course;
use Modules\LMS\Models\CourseSection;
use Modules\LMS\Models\SectionContent;

class CourseSectionSeeder extends Seeder
{
    public function run(): void
    {
        $courses = Course::all();

        if ($courses->isEmpty()) {
            $this->command->warn('Courses kosong.');
            return;
        }

        $curriculum = [
            'Modul 1: Landasan & Konsep Dasar' => [
                'Pengantar dan Regulasi Acuan',
                'Prinsip Utama dan Ruang Lingkup',
            ],
            'Modul 2: Metodologi & Instrumen Analisis' => [
                'Teknik Pengumpulan Data Lapangan',
                'Formula Perhitungan dan Proyeksi',
            ],
            'Modul 3: Implementasi & Studi Kasus' => [
                'Simulasi Penghitungan Data Nyata',
                'Penyusunan Laporan dan Rekomendasi',
            ],
        ];

        $defaultContent = <<<'HTML'
<p class="ql-align-justify">Perencanaan Tenaga Kerja Makro (PTK Makro) merupakan proses penyusunan rencana ketenagakerjaan secara sistematis yang memuat upaya pendayagunaan tenaga kerja secara optimal dan produktif guna menopang pertumbuhan ekonomi maupun sosial, baik dalam cakupan nasional, daerah, maupun sektoral. Hasil akhir dari proses perencanaan sistematis ini dituangkan ke dalam dokumen resmi bernama <strong>Rencana Tenaga Kerja Makro (RTK Makro)</strong> yang berlaku untuk jangka waktu 5 (lima) tahun. Dalam arsitektur pembangunan nasional dan daerah, RTK Makro berfungsi sebagai kompas strategis agar laju investasi dan pertumbuhan ekonomi tidak berjalan sendiri tanpa kesiapan sumber daya manusia, sekaligus memastikan bahwa penciptaan lapangan kerja baru mampu mengimbangi pertambahan angkatan kerja setiap tahunnya.</p><p class="ql-align-justify"><br></p><p class="ql-align-justify">Penyusunan RTK Makro di Indonesia berdiri di atas pijakan regulasi yang berjenjang dan mengikat bagi instansi pembina ketenagakerjaan maupun sektor terkait. Payung hukum utamanya berakar pada Undang-Undang Nomor 13 Tahun 2003 tentang Ketenagakerjaan serta Peraturan Pemerintah Nomor 15 Tahun 2007 tentang Tata Cara Memperoleh Informasi Ketenagakerjaan dan Penyusunan serta Pelaksanaan Perencanaan Tenaga Kerja. Secara operasional, pedoman metodologisnya dijabarkan lebih rinci melalui Peraturan Menteri Tenaga Kerja dan Transmigrasi Nomor PER.16/MEN/XI/2010 tentang Perencanaan Tenaga Kerja Makro serta Keputusan Menteri Tenaga Kerja dan Transmigrasi Nomor 309 Tahun 2013 tentang Pedoman Penyusunan Perencanaan Tenaga Kerja Provinsi dan Kabupaten/Kota. Regulasi tersebut juga menegaskan batas pemisah yang jelas antara <strong>RTK Makro </strong>yang disusun oleh pemerintah untuk memetakan dinamika pasar kerja lintas wilayah atau lapangan usaha dengan <strong>RTK Mikro</strong>, yang disusun oleh korporasi, BUMN, BUMD, atau instansi tunggal untuk mengatur kebutuhan sumber daya manusia di lingkup internal organisasinya.</p><p class="ql-align-justify"><br></p><p class="ql-align-justify">Sebelum membedah formulasi matematis di balik proyeksi lima tahunan, pemahaman utuh mengenai anatomi pasar kerja dari hulu demografi hingga hilir penyerapan industri menjadi prasyarat mutlak bagi setiap perencana. Seluruh rangkaian analisis dalam RTK Makro pada hakikatnya bertumpu pada tiga pilar perhitungan yang saling mengunci, yaitu penghitungan persediaan tenaga kerja (<em>labor supply</em>), penghitungan kebutuhan atau kesempatan kerja (<em>labor demand</em>), serta penyusunan neraca tenaga kerja (<em>labor balance</em>). Gambaran menyeluruh mengenai bagaimana ketiga pilar tersebut berinteraksi dalam siklus pembangunan ketenagakerjaan dapat disimak terlebih dahulu melalui materi pengantar berikut ini.</p><p class="ql-align-justify"><br></p><p class="ql-align-justify">Sebagaimana tergambar pada alur visual ketenagakerjaan, titik tolak analisis ketenagakerjaan selalu dimulai dari pemetaan struktur penduduk di suatu wilayah. Dalam standar statistik ketenagakerjaan nasional, populasi dibagi berdasarkan batas usia kerja untuk mengidentifikasi <strong>Penduduk Usia Kerja (PUK)</strong>, yakni seluruh penduduk yang telah menginjak usia 15 tahun ke atas. Kelompok PUK ini selanjutnya terbelah menjadi dua komponen besar: <strong>Angkatan Kerja (AK)</strong>, yang mencakup penduduk yang sudah bekerja maupun penganggur terbuka yang aktif mencari atau mempersiapkan usaha, serta <strong>Bukan Angkatan Kerja (BAK)</strong>, yang meliputi penduduk usia kerja yang masih bersekolah, mengurus rumah tangga, atau penerima pendapatan seperti pensiunan.</p><p class="ql-align-justify"><br></p><p class="ql-align-justify">Untuk mengukur seberapa besar proporsi penduduk usia kerja yang aktif terlibat di pasar kerja serta seberapa besar tekanan pengangguran pada tahun dasar (<em>baseline</em>), penyusunan RTK Makro menggunakan tiga persamaan indikator fundamental ketenagakerjaan:</p><p class="ql-align-justify"><br></p><p class="ql-align-center"><span style="font-size: 18px;"><span class="ql-formula" data-value="PUK = P - P_{u15}"><span contenteditable="false"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>P</mi><mi>U</mi><mi>K</mi><mo>=</mo><mi>P</mi><mo>−</mo><msub><mi>P</mi><mrow><mi>u</mi><mn>15</mn></mrow></msub></mrow><annotation encoding="application/x-tex">PUK = P - P_{u15}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height: 0.6833em;"></span><span class="mord mathnormal" style="margin-right: 0.1389em;">P</span><span class="mord mathnormal" style="margin-right: 0.109em;">U</span><span class="mord mathnormal" style="margin-right: 0.0715em;">K</span><span class="mspace" style="margin-right: 0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right: 0.2778em;"></span></span><span class="base"><span class="strut" style="height: 0.7667em; vertical-align: -0.0833em;"></span><span class="mord mathnormal" style="margin-right: 0.1389em;">P</span><span class="mspace" style="margin-right: 0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right: 0.2222em;"></span></span><span class="base"><span class="strut" style="height: 0.8333em; vertical-align: -0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right: 0.1389em;">P</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height: 0.3011em;"><span class="" style="top: -2.55em; margin-left: -0.1389em; margin-right: 0.05em;"><span class="pstrut" style="height: 2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">u</span><span class="mord mtight">15</span></span></span></span></span><span class="vlist-s"></span></span><span class="vlist-r"><span class="vlist" style="height: 0.15em;"><span class=""></span></span></span></span></span></span></span></span></span></span></span> </span></p><p class="ql-align-center"><br></p><p class="ql-align-center"><span style="font-size: 18px;"><span class="ql-formula" data-value="TPAK = \frac{AK}{PUK} \times 100\%"><span contenteditable="false"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>T</mi><mi>P</mi><mi>A</mi><mi>K</mi><mo>=</mo><mfrac><mrow><mi>A</mi><mi>K</mi></mrow><mrow><mi>P</mi><mi>U</mi><mi>K</mi></mrow></mfrac><mo>×</mo><mn>100</mn><mi mathvariant="normal">%</mi></mrow><annotation encoding="application/x-tex">TPAK = \frac{AK}{PUK} \times 100\%</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height: 0.6833em;"></span><span class="mord mathnormal" style="margin-right: 0.1389em;">TP</span><span class="mord mathnormal">A</span><span class="mord mathnormal" style="margin-right: 0.0715em;">K</span><span class="mspace" style="margin-right: 0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right: 0.2778em;"></span></span><span class="base"><span class="strut" style="height: 1.2173em; vertical-align: -0.345em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height: 0.8723em;"><span class="" style="top: -2.655em;"><span class="pstrut" style="height: 3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right: 0.1389em;">P</span><span class="mord mathnormal mtight" style="margin-right: 0.109em;">U</span><span class="mord mathnormal mtight" style="margin-right: 0.0715em;">K</span></span></span></span><span class="" style="top: -3.23em;"><span class="pstrut" style="height: 3em;"></span><span class="frac-line" style="border-bottom-width: 0.04em;"></span></span><span class="" style="top: -3.394em;"><span class="pstrut" style="height: 3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">A</span><span class="mord mathnormal mtight" style="margin-right: 0.0715em;">K</span></span></span></span></span><span class="vlist-s"></span></span><span class="vlist-r"><span class="vlist" style="height: 0.345em;"><span class=""></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mspace" style="margin-right: 0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right: 0.2222em;"></span></span><span class="base"><span class="strut" style="height: 0.8056em; vertical-align: -0.0556em;"></span><span class="mord">100%</span></span></span></span></span></span> </span></p><p class="ql-align-center"><br></p><p class="ql-align-center"><span style="font-size: 18px;"><span class="ql-formula" data-value="TPT = \frac{PT}{AK} \times 100\%"><span contenteditable="false"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>T</mi><mi>P</mi><mi>T</mi><mo>=</mo><mfrac><mrow><mi>P</mi><mi>T</mi></mrow><mrow><mi>A</mi><mi>K</mi></mrow></mfrac><mo>×</mo><mn>100</mn><mi mathvariant="normal">%</mi></mrow><annotation encoding="application/x-tex">TPT = \frac{PT}{AK} \times 100\%</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height: 0.6833em;"></span><span class="mord mathnormal" style="margin-right: 0.1389em;">TPT</span><span class="mspace" style="margin-right: 0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right: 0.2778em;"></span></span><span class="base"><span class="strut" style="height: 1.2173em; vertical-align: -0.345em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height: 0.8723em;"><span class="" style="top: -2.655em;"><span class="pstrut" style="height: 3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">A</span><span class="mord mathnormal mtight" style="margin-right: 0.0715em;">K</span></span></span></span><span class="" style="top: -3.23em;"><span class="pstrut" style="height: 3em;"></span><span class="frac-line" style="border-bottom-width: 0.04em;"></span></span><span class="" style="top: -3.394em;"><span class="pstrut" style="height: 3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">PT</span></span></span></span></span><span class="vlist-s"></span></span><span class="vlist-r"><span class="vlist" style="height: 0.345em;"><span class=""></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mspace" style="margin-right: 0.2222em;"></span><span class="mbin">×</span><span class="mspace" style="margin-right: 0.2222em;"></span></span><span class="base"><span class="strut" style="height: 0.8056em; vertical-align: -0.0556em;"></span><span class="mord">100%</span></span></span></span></span></span> </span></p><p class="ql-align-justify"><br></p><p class="ql-align-justify">Melalui ketiga persamaan dasar tersebut, variabel P melambangkan total populasi penduduk keseluruhan dan <span class="ql-formula" data-value="P_{u15}"><span contenteditable="false"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><msub><mi>P</mi><mrow><mi>u</mi><mn>15</mn></mrow></msub></mrow><annotation encoding="application/x-tex">P_{u15}</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height: 0.8333em; vertical-align: -0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right: 0.1389em;">P</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height: 0.3011em;"><span class="" style="top: -2.55em; margin-left: -0.1389em; margin-right: 0.05em;"><span class="pstrut" style="height: 2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">u</span><span class="mord mtight">15</span></span></span></span></span><span class="vlist-s"></span></span><span class="vlist-r"><span class="vlist" style="height: 0.15em;"><span class=""></span></span></span></span></span></span></span></span></span></span></span> menyatakan jumlah penduduk berusia di bawah 15 tahun. Indikator <strong>Tingkat Partisipasi Angkatan Kerja (<span class="ql-formula" data-value="TPAK"><span contenteditable="false"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>T</mi><mi>P</mi><mi>A</mi><mi>K</mi></mrow><annotation encoding="application/x-tex">TPAK</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height: 0.6833em;"></span><span class="mord mathnormal" style="margin-right: 0.1389em;">TP</span><span class="mord mathnormal">A</span><span class="mord mathnormal" style="margin-right: 0.0715em;">K</span></span></span></span></span></span> )</strong> mengukur persentase penduduk usia kerja yang masuk ke dalam bursa kerja (<span class="ql-formula" data-value="AK"><span contenteditable="false"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>A</mi><mi>K</mi></mrow><annotation encoding="application/x-tex">AK</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height: 0.6833em;"></span><span class="mord mathnormal">A</span><span class="mord mathnormal" style="margin-right: 0.0715em;">K</span></span></span></span></span></span> ), di mana nilai <strong> (<span class="ql-formula" data-value="TPAK"><span contenteditable="false"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>T</mi><mi>P</mi><mi>A</mi><mi>K</mi></mrow><annotation encoding="application/x-tex">TPAK</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height: 0.6833em;"></span><span class="mord mathnormal" style="margin-right: 0.1389em;">TP</span><span class="mord mathnormal">A</span><span class="mord mathnormal" style="margin-right: 0.0715em;">K</span></span></span></span></span></span> )</strong> yang semakin tinggi mengindikasikan semakin besarnya pasokan tenaga kerja potensial yang siap berproduksi. Sebaliknya, <strong>Tingkat Pengangguran Terbuka (<span class="ql-formula" data-value="TPT"><span contenteditable="false"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>T</mi><mi>P</mi><mi>T</mi></mrow><annotation encoding="application/x-tex">TPT</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height: 0.6833em;"></span><span class="mord mathnormal" style="margin-right: 0.1389em;">TPT</span></span></span></span></span></span>)</strong> mengukur rasio jumlah penganggur terbuka (<span class="ql-formula" data-value="PT"><span contenteditable="false"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>P</mi><mi>T</mi></mrow><annotation encoding="application/x-tex">PT</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height: 0.6833em;"></span><span class="mord mathnormal" style="margin-right: 0.1389em;">PT</span></span></span></span></span></span> ) terhadap total angkatan kerja (<span class="ql-formula" data-value="AK"><span contenteditable="false"><span class="katex"><span class="katex-mathml"><math xmlns="http://www.w3.org/1998/Math/MathML"><semantics><mrow><mi>A</mi><mi>K</mi></mrow><annotation encoding="application/x-tex">AK</annotation></semantics></math></span><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height: 0.6833em;"></span><span class="mord mathnormal">A</span><span class="mord mathnormal" style="margin-right: 0.0715em;">K</span></span></span></span></span></span>), yang menjadi tolok ukur utama keberhasilan daerah maupun nasional dalam menyerap pasokan tenaga kerja yang tersedia.</p><p class="ql-align-justify"><br></p><p class="ql-align-justify"><br></p><p class="ql-align-justify"><br></p><p><br></p>
HTML;

        foreach ($courses as $course) {
            $posSection = 1;
            foreach ($curriculum as $sectionTitle => $contentTitles) {
                $section = CourseSection::updateOrCreate(
                    [
                        'course_id' => $course->id,
                        'name'      => $sectionTitle,
                    ],
                    [
                        'description' => 'Pembahasan modul mengenai ' . strtolower($sectionTitle),
                        'position'    => $posSection++,
                    ]
                );

                $posContent = 1;
                foreach ($contentTitles as $title) {
                    SectionContent::updateOrCreate(
                        [
                            'course_section_id' => $section->id,
                            'name'              => $title,
                        ],
                        [
                            'content_text' => $defaultContent,
                            'position'     => $posContent++,
                        ]
                    );
                }
            }
        }

        $this->command->info("CourseSectionSeeder materi & isi dummy berhasil dibuat 🚀");
    }
}
